'use strict';
window.createPhoenixExplorationUI=function({state,tasks,hubs,navigate,progressUI,engine}){
 const {categories,details}=window.PHOENIX_EXPLORATION,artwork=window.PHOENIX_EXPLORATION_ART;
 const artFor=id=>{if(!artwork[id])throw Error('Missing White Orchard art: '+id);return artwork[id];};
 function applyArt(section,art){section.style.setProperty('--exploration-art','url('+art.src+')');section.style.setProperty('--exploration-art-focus',art.focus);section.dataset.artKind=art.kind;}
 const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
 const link=(text,href,cls)=>{const e=make('a',text,cls);e.href=href;return e;};
 function categoryBack(text){const a=link(text,'#whiteorchard-console','exploration-home');a.onclick=e=>{e.preventDefault();restore(history.state?.explorationDeckReturn,'#whiteorchard-console');};return a;}
 let restoration=null;
 const decks=new Map(),entryViews=new Set(Object.keys(details).map(id=>tasks[id].view));
 function card(name,href,art,caption){const a=link('',href,'diagram-card exploration-card'),im=make('img');im.src=art.src;im.alt='';im.loading='lazy';im.style.objectPosition=art.focus;a.dataset.artKind=art.kind;const kind=make('span',art.kind==='illustration'?'Illustrated scene':art.kind==='map'?'Location map':art.kind==='landmark'?'Local landmark':'In-game scene','exploration-art-kind');a.append(im,kind,make('strong',name),make('small',caption));return a;}
 function rail(host,name){const e=make('nav',null,'diagram-rail exploration-rail');e.tabIndex=0;e.setAttribute('aria-label',name);const tools=make('div',null,'diagram-browse'),prev=make('button','← Previous'),next=make('button','Next →');prev.type=next.type='button';prev.setAttribute('aria-label','Previous '+name);next.setAttribute('aria-label','Next '+name);prev.onclick=()=>e.scrollBy({left:-250,behavior:'auto'});next.onclick=()=>e.scrollBy({left:250,behavior:'auto'});tools.append(prev,make('span','Swipe to browse'),next);host.append(e,tools);return e;}
 const diagramDirectory=document.getElementById('gear-diagrams');diagramDirectory.classList.add('ad-diagram-directory');applyArt(diagramDirectory,artFor('category-diagrams'));
 const categoryRail=document.querySelector('.diagram-category-section .diagram-rail');categoryRail.replaceChildren(card('Diagrams','#gear-diagrams',artFor('category-diagrams'),'Shared acquisition entries'));

 for(const c of categories){
  categoryRail.append(card(c.name,'#exploration-'+c.id,artFor('category-'+c.id),'Open activity deck'));
  const view=make('section',null,'view scene diagram-view exploration-deck');view.id='exploration-'+c.id;view.hidden=true;applyArt(view,artFor('category-'+c.id));
  const inner=make('div',null,'scene-inner');inner.append(categoryBack('← White Orchard'),make('p','WHITE ORCHARD / EXPLORATION','eyebrow'),make('h1',c.name),make('p',c.intro,'lead'),make('p','Suggested travel order. Open any stop; check the live threat before committing.','exploration-route-note'));
  const jump=make('select');jump.setAttribute('aria-label','Find '+c.name.toLowerCase());jump.append(make('option','Find an activity…'));jump.firstChild.value='';for(const [index,id] of c.ids.entries()){const opt=make('option',(index+1)+'. '+tasks[id].name);opt.value=id;jump.append(opt);}jump.onchange=()=>{if(jump.value)navigate('#'+tasks[jump.value].view);};inner.append(jump);
  const activeHost=make('section'),active=rail(activeHost,c.name+' route');inner.append(activeHost);
  const empty=make('p','Every listed stop is recorded complete. Reopen Completed to review or correct a mark.','exploration-empty');inner.append(empty);
  const completed=make('details',null,'exploration-completed');completed.append(make('summary','Completed'));const done=rail(completed,'completed '+c.name.toLowerCase());inner.append(completed);
  const cards=new Map();for(const [index,id] of c.ids.entries()){const e=card(tasks[id].name,'#'+tasks[id].view,artFor(id),'Route '+String(index+1).padStart(2,'0')+' · '+details[id].threat);e.dataset.explorationCard=id;cards.set(id,e);active.append(e);}
  const numbers=window.createPhoenixDeckJump(c.ids.map(id=>tasks[id].name),0,index=>{
   const target=cards.get(c.ids[index]);
   if(target.parentElement===done)completed.open=true;
   const host=target.parentElement;
   host.scrollLeft+=target.getBoundingClientRect().left-host.getBoundingClientRect().left;
   target.focus({preventScroll:true});
   numbers.update(index);numbers.center(index);
  });
  activeHost.append(numbers.frame);
  inner.append(categoryBack('All activity categories'));view.append(inner);document.querySelector('main').append(view);decks.set(c.id,{view,active,done,completed,empty,jump,cards});
 }
 function controls(id){const d=details[id],box=make('section',null,'exploration-record'),label=make('label',null,'diagram-acquired'),check=make('input');check.type='checkbox';check.dataset.complete=id;check.setAttribute('aria-label','Mark '+tasks[id].name+' completed');label.append(check,make('span',id==='cow-pasture-warning'?'Warning reviewed':categories.find(c=>c.ids.includes(id)).id==='travel'?'Signpost discovered':categories.find(c=>c.ids.includes(id)).id==='preparation'?'Station used':'Activity completed'));box.append(label,make('p','Done means: '+d.done,'completion-meaning'));const undo=make('button','Undo last progress change');undo.type='button';undo.dataset.explorationUndo='';undo.onclick=()=>progressUI.undoLast();box.append(undo);return box;}
 for(const [id,d] of Object.entries(details)){
  const task=tasks[id],section=document.getElementById(task.view),panel=section.querySelector('.reading-panel'),c=categories.find(c=>c.id===d.category);section.classList.add('exploration-detail');applyArt(section,artFor(id));
  const back=make('button','Return to activity deck');back.type='button';back.dataset.explorationReturn='';back.onclick=()=>restore(history.state?.explorationReturn,'#exploration-'+d.category);const nav=make('nav',null,'diagram-detail-actions');nav.append(back,link(c.name,'#exploration-'+d.category));
  const article=make('section',null,'exploration-guidance');article.append(nav);const art=artFor(id);article.append(make('p',(art.kind==='illustration'?'Illustrated scene':art.kind==='map'?'Location map':art.kind==='landmark'?'Local landmark':'In-game scene')+' · '+art.caption,'exploration-art-caption'));
  if(d.risk)article.append(make('p',d.risk,'risk-note'));
  if(d.uncertainty)article.append(make('p','Provisional detail: '+d.uncertainty,'exploration-uncertainty'));
  article.append(make('h2','Approach'),make('p',d.approach),make('h2','Threat & preparation'),make('p',d.threat));
  if(Number.isFinite(task.level))article.append(make('p','Suggested quest level '+task.level+'. This is the quest recommendation, not a fixed enemy level.','exploration-level'));
  article.append(make('h2','Actions'));const steps=make('ol');d.steps.forEach(s=>steps.append(make('li',s)));article.append(steps,make('h2','Verified rewards'),make('p',d.fixed),make('h2','Possible variable loot'),make('p',d.variable));
  const map=link('Locate this activity on the map','#whiteorchard-map/'+id,'primary-action');map.dataset.exactLocation='';article.append(map,controls(id));
  const connections=make('nav',null,'diagram-cluster-links');connections.setAttribute('aria-label','Related entries');for(const target of d.links){const t=tasks[target];if(!t)continue;const merchant=window.PHOENIX_MAP.markers.find(p=>p.task===target&&p.type==='service');connections.append(link(t.name,merchant?'#economy-merchants/'+merchant.id:'#'+t.view));}if(connections.children.length)article.append(make('h2','Related entries'),connections);
  const clusters=make('nav',null,'diagram-cluster-links');for(const h of hubs.filter(h=>h.items.includes(id)))clusters.append(link(h.name,'#whiteorchard-tree/'+h.id+'/'+id));if(clusters.children.length)article.append(make('h2','Nearby quest clusters'),clusters);

  if(task.stages){panel.prepend(article);const expandable=make('details',null,'exploration-quest-steps');expandable.append(make('summary','Quest walkthrough & objective controls'));const nodes=[...panel.children].filter(n=>n!==article);nodes.forEach(n=>expandable.append(n));panel.append(expandable);}else panel.replaceChildren(article);
 }
 function snapshot(){const root=document.querySelector('.view:not([hidden])')?.id,deck=[...decks.values()].find(d=>d.view.id===root);return {entryReturn:history.state?.explorationReturn,deckReturn:history.state?.explorationDeckReturn,hash:location.hash||'#whiteorchard-console',y:(window.PhoenixViewport||window).scrollY,tree:history.state?.tree,categoryX:categoryRail.scrollLeft,deck:deck?{id:root,activeX:deck.active.scrollLeft,doneX:deck.done.scrollLeft,open:deck.completed.open}:null};}
 const priorCapture=window.PhoenixDiagramRoutes.capture;
 window.PhoenixDiagramRoutes.capture=function(hash){const base=priorCapture(hash),id=hash.slice(1).split('/')[0],current=document.querySelector('.view:not([hidden])');if(restoration)return {...base,explorationReturn:restoration.entryReturn,explorationDeckReturn:restoration.deckReturn};if([...decks.values()].some(d=>d.view.id===id)){const returning=current?.classList.contains('exploration-detail')&&history.state?.explorationReturn?.hash?.split('/')[0]==='#'+id;return {...base,explorationDeckReturn:returning?history.state.explorationDeckReturn:snapshot()};}if(entryViews.has(id)){base.explorationDeckReturn=history.state?.explorationDeckReturn;if(current?.id===id)return {...base,explorationReturn:history.state?.explorationReturn};const returning=history.state?.explorationSource?.hash?.split('/')[0]==='#'+id;return {...base,explorationReturn:returning?history.state.explorationReturn:snapshot()};}if(hash.startsWith('#whiteorchard-map/')&&current?.classList.contains('exploration-detail'))return {...base,explorationSource:snapshot(),explorationReturn:history.state?.explorationReturn,explorationDeckReturn:history.state?.explorationDeckReturn};return base;};
 function restore(origin,fallback){const hash=origin?.hash?.startsWith('#whiteorchard-map')?'#whiteorchard-map/restore':origin?.hash||fallback;restoration=origin||{};try{navigate(hash,origin?.tree?{tree:origin.tree}:{});}finally{restoration=null;}if(origin)requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{categoryRail.scrollLeft=origin.categoryX||0;const d=[...decks.values()].find(d=>d.view.id===origin.deck?.id);if(d){d.completed.open=origin.deck.open;d.active.scrollLeft=origin.deck.activeX;d.done.scrollLeft=origin.deck.doneX;}(window.PhoenixViewport||window).scrollTo(0,origin.y||0);})));}
 const mapBack=make('button','Return to activity');mapBack.type='button';mapBack.className='diagram-map-return';mapBack.hidden=true;mapBack.onclick=()=>restore(history.state?.explorationSource,'#whiteorchard-console');document.querySelector('#whiteorchard-map .scene-inner').prepend(mapBack);
 const beast=document.getElementById(tasks['q-beast'].view),skullRisk=make('p','Before completing the griffin quest: collect the crystal skull at the opening camp if you want it. It is reported to disappear when The Beast of White Orchard is completed.','risk-note');beast.querySelector('.reading-panel').prepend(skullRisk);let skullQueued=false;
 function refresh(){for(const [cid,d] of decks){const c=categories.find(c=>c.id===cid);for(const [index,id] of c.ids.entries()){const el=d.cards.get(id),done=state.completed[id]===true,closed=window.PHOENIX_PROGRESS_DATA.quests[id]&&['failed','unavailable'].includes(engine.status(id,state.progress));el.classList.toggle('is-acquired',done);el.querySelector('small').textContent=(done?'✓ Completed':closed?engine.status(id,state.progress):'Route '+String(index+1).padStart(2,'0'))+(Number.isFinite(tasks[id].level)?' · Suggested level '+tasks[id].level:'')+' · '+details[id].threat;const host=done?d.done:d.active;if(el.parentElement!==host||host.children[index]!==el)host.append(el);}
   d.completed.hidden=!d.done.children.length;d.empty.hidden=!!d.active.children.length;
  }document.querySelectorAll('[data-exploration-undo]').forEach(b=>b.disabled=!state.progressUndo);document.querySelectorAll('.exploration-detail [data-complete]').forEach(b=>b.checked=state.completed[b.dataset.complete]===true);mapBack.hidden=!history.state?.explorationSource;
  skullRisk.hidden=state.completed['poi-4']===true;const current=document.querySelector('.view:not([hidden])');if(current?.classList.contains('exploration-detail')&&location.hash.includes('/')){const steps=current.querySelector('.exploration-quest-steps');if(steps)steps.open=true;}if(current===beast&&!state.completed['poi-4']&&!skullQueued&&!engine.facts(state.progress).griffin){skullQueued=true;window.__phoenixMedallion?.enqueueWarning({id:'crystal-skull-cutoff',text:window.PhoenixWarningCatalog?.get('poi-4',tasks).short||skullRisk.textContent,href:'#'+tasks['poi-4'].view,isValid:()=>!state.completed['poi-4']&&!engine.facts(state.progress).griffin});}window.__phoenixMedallion?.reconcileWarnings();
  const back=document.querySelector('.exploration-detail:not([hidden]) [data-exploration-return]');if(back){const h=history.state?.explorationReturn?.hash||'';back.textContent=h.startsWith('#whiteorchard-tree')?'Return to cluster':h.startsWith('#whiteorchard-map')?'Return to map':h.startsWith('#exploration-')?'Return to activity deck':h?'Return to origin':'Return to activity deck';}
 }
 addEventListener('phoenix:route-rendered',refresh);addEventListener('phoenix:progress-committed',refresh);addEventListener('phoenix:progress-undone',refresh);refresh();
};
